<?php
declare(strict_types=1);
namespace HardnessMcp\Tools\Order;
use HardnessMcp\Tools\ToolDefinition;
final class OrderBacklogDefinition { public function toToolDefinition():ToolDefinition{$groups=['day','week','month','customer','seller_internal','status','document'];return new ToolDefinition('hardness.order.summary','Returns order reports. Use document to list individual orders with issue date, customer, customer group, proposal customer when available, status, and total; other groupings return totals, trends, and rankings. It includes every order by default; use the status filter when a specific situation is needed. Historical summaries grouped by month, customer, internal seller, or status accept up to 5 years. Weekly grouping and document listings accept up to 12 months; daily grouping accepts up to 90 days. Rankings and document listings return at most 50 rows. Never split a period longer than these limits into sequential calls: explain the applicable interactive limit and request one allowed period instead.',['type'=>'object','properties'=>['date_from'=>['type'=>'string','minLength'=>10,'maxLength'=>10],'date_to'=>['type'=>'string','minLength'=>10,'maxLength'=>10],'group_by'=>['type'=>'string','enum'=>$groups],'customer_id'=>['type'=>'integer','minimum'=>1],'seller_internal_id'=>['type'=>'integer','minimum'=>1],'status'=>['type'=>'integer','minimum'=>0],'limit'=>['type'=>'integer','minimum'=>1,'maximum'=>50]],'required'=>['date_from','date_to','group_by'],'additionalProperties'=>false],['order:report:read']);}}
